enum CursorError: Error { case repeated }
func checkedCursor(previous: String?, next: String?) throws -> String? {
    if let next, next == previous { throw CursorError.repeated }
    return next
}
let continued = try checkedCursor(previous: "a", next: "b")
assert(continued == "b")
let ended = try checkedCursor(previous: "a", next: nil)
assert(ended == nil)
do {
    _ = try checkedCursor(previous: "a", next: "a")
    assertionFailure("Нужно обнаружить зацикливание")
} catch { assert(error is CursorError) }

Повтор токена прекращает зацикливание; nil не считается повтором первой страницы и означает финальный ответ.

struct SaveIntent: Equatable { let token: String; let value: Bool }
func acknowledge(_ token: String, current: SaveIntent?) -> SaveIntent? {
    current?.token == token ? nil : current
}
let pending = SaveIntent(token: "second", value: false)
assert(acknowledge("first", current: pending) == pending)
assert(acknowledge("second", current: pending) == nil)

Серверная часть ответа уже применена по условию. Подтверждение относится к операции, не просто к post. Старый ответ не стирает более новое намерение пользователя.

func hitRatio(hits: Int, misses: Int) -> Double? {
    guard hits >= 0, misses >= 0 else { return nil }
    let total = Double(hits) + Double(misses)
    guard total > 0 else { return nil }
    return Double(hits) / total
}
assert(hitRatio(hits: 3, misses: 1) == 0.75)
assert(hitRatio(hits: 0, misses: 0) == nil)
assert(hitRatio(hits: -1, misses: 2) == nil)

Знаменатель — все обращения. Преобразование в Double до сложения избегает переполнения суммы Int в этой небольшой функции.
